bool FrameDataTable::Get(int chara, int pattern, Pattern& out)
{
	for (const Chara& entry : kCharas)
	{
		if (entry.number != chara)
			continue;

		for (int i = 0; i < entry.count; ++i)
		{
			if (entry.rows[i].pattern != pattern)
				continue;

			out.length = entry.rows[i].length;
			out.startup = entry.rows[i].startup;
			out.active = entry.rows[i].active;
			out.invulnFrames = entry.rows[i].invulnFrames;
			out.invulnKind = entry.rows[i].invulnKind;
			out.etcStart = entry.rows[i].etcStart;
			out.etcFrames = entry.rows[i].etcFrames;
			out.etcBoxes = entry.rows[i].etcBoxes;
			return true;
		}

		return false;
	}

	return false;
}

int FrameDataTable::GetCharaCount()
{
	return sizeof(kCharas) / sizeof(kCharas[0]);
}
